-- 2026-09-01-product-release-stage-and-marketing.sql
-- Stage 1(产品化升级):产品成熟度轴 release_stage(正式版/公测版/开发中)+ 营销内容 marketing(jsonb)
--   + 现有产品营销回填 + 把 12 个开发中智能体从「website 写死」迁为真产品行(release_stage=developing)。
-- 幂等:列用 IF NOT EXISTS、CHECK 用 DO 卫、INSERT 用 ON CONFLICT DO NOTHING。
BEGIN;

-- ① 成熟度轴 release_stage(与 status/visibility/type/origin 正交)。
--    存量都是已上线 → 默认 'ga' 回填;之后新产品默认 'developing'(未成熟)。
ALTER TABLE product.products ADD COLUMN IF NOT EXISTS release_stage varchar(16) NOT NULL DEFAULT 'ga';
ALTER TABLE product.products ALTER COLUMN release_stage SET DEFAULT 'developing';
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'product.products'::regclass AND conname = 'chk_products_release_stage'
  ) THEN
    ALTER TABLE product.products
      ADD CONSTRAINT chk_products_release_stage CHECK (release_stage IN ('ga','beta','developing'));
  END IF;
END $$;
CREATE INDEX IF NOT EXISTS idx_products_release_stage ON product.products (release_stage);

-- ② 营销内容 marketing(jsonb,双语富结构 {zh|en:{tagline,value,highlights[],tags[],industries[],detail}})。
ALTER TABLE product.products ADD COLUMN IF NOT EXISTS marketing jsonb;

-- ③ 列锁:platform_svc 可写新列(与 40/98 GRANT 白名单同步)。
GRANT UPDATE (release_stage, marketing) ON product.products TO platform_svc;

-- ④ 现有产品营销回填(value 从官网写死迁入;仅当 marketing 尚空)。
UPDATE product.products SET marketing = '{"zh":{"tagline":"L2 · 数据智能","value":"让数据可治理、可信赖、可复用，为上层智能应用提供高质量数据供给。","highlights":[],"tags":[],"industries":[],"detail":""},"en":{"tagline":"L2 · Data intelligence","value":"Make data governable, trustworthy and reusable — high-quality supply for every intelligent app above.","highlights":[],"tags":[],"industries":[],"detail":""}}'::jsonb WHERE product_code = 'arda' AND marketing IS NULL;
UPDATE product.products SET marketing = '{"zh":{"tagline":"L1 · 模型底座","value":"把大模型能力沉淀为企业可控、可复用的模型服务底座。","highlights":[],"tags":[],"industries":[],"detail":""},"en":{"tagline":"L1 · Model foundation","value":"Turn large-model capability into a controllable, reusable model foundation.","highlights":[],"tags":[],"industries":[],"detail":""}}'::jsonb WHERE product_code = 'atlas' AND marketing IS NULL;
UPDATE product.products SET marketing = '{"zh":{"tagline":"L1 · 能力编排","value":"以搭积木的方式快速组装 AI 应用，缩短从能力到业务的路径。","highlights":[],"tags":[],"industries":[],"detail":""},"en":{"tagline":"L1 · Ability orchestration","value":"Assemble AI apps like building blocks — shorten the path from capability to business.","highlights":[],"tags":[],"industries":[],"detail":""}}'::jsonb WHERE product_code = 'runos' AND marketing IS NULL;
UPDATE product.products SET marketing = '{"zh":{"tagline":"L2 · 知识智能","value":"把散落的企业知识变成可检索、可推理的智能资产。","highlights":[],"tags":[],"industries":[],"detail":""},"en":{"tagline":"L2 · Knowledge intelligence","value":"Turn scattered enterprise knowledge into retrievable, reasoning-ready assets.","highlights":[],"tags":[],"industries":[],"detail":""}}'::jsonb WHERE product_code = 'karda' AND marketing IS NULL;

-- ⑤ 12 个开发中智能体入库(草稿名沿用备份;release_stage=developing;is_customer_visible=true
--    上站——本 PR 同时上线 website 三态渲染,广场按 release_stage 显示「开发中」徽标+敬请期待;
--    ON CONFLICT 幂等)。营销内容含能力/标签/行业(备份全字段)。
