  (gen_random_uuid(), 'contractaudit', 'general_agent', 1, '合同审核智能体', 'Contract Review Agent', '面向采购、销售、法务和项目管理场景，自动识别合同条款风险、缺失条款、履约节点和审批关注点。', 'product.product.contractaudit.desc', ARRAY['大模型','知识库','合规审查']::text[], 'developing', 'active', true, true, 'self', '{"zh":{"tagline":"数字员工 · 通用类","value":"减少人工逐条审阅成本，让业务部门在提交审批前就能得到结构化风险提示。","highlights":["条款风险识别","标准模板比对","审批意见生成"],"tags":["大模型","知识库","合规审查"],"industries":["general","legal"],"detail":""},"en":{"tagline":"Digital Employee · General","value":"Reduces manual review effort and gives business teams structured risk hints before approval submission.","highlights":["Clause risk detection","Template comparison","Approval comment drafting"],"tags":["LLM","Knowledge Base","Compliance Review"],"industries":["general","legal"],"detail":""}}'::jsonb),
  (gen_random_uuid(), 'digitallegal', 'general_agent', 1, '数字法务智能体', 'Digital Legal Agent', '沉淀企业制度、法律法规、历史案件和问答知识，为员工提供法务咨询、制度检索和材料草拟支持。', 'product.product.digitallegal.desc', ARRAY['大模型问答','RAG','企业知识']::text[], 'developing', 'active', true, true, 'self', '{"zh":{"tagline":"数字员工 · 通用类","value":"把常见法务咨询从人工响应转为自助问答，并保留引用来源与审核链路。","highlights":["法规制度问答","函件草拟","风险解释与引用追溯"],"tags":["大模型问答","RAG","企业知识"],"industries":["general","legal"],"detail":""},"en":{"tagline":"Digital Employee · General","value":"Turns common legal questions into self-service answers while keeping citations and review trails.","highlights":["Policy Q&A","Legal letter drafting","Risk explanation with citations"],"tags":["LLM Q&A","RAG","Enterprise Knowledge"],"industries":["general","legal"],"detail":""}}'::jsonb),
  (gen_random_uuid(), 'bizinsight', 'general_agent', 1, '经营分析智能体', 'Business Analysis Agent', '连接经营指标、财务数据、客户数据和项目进度，自动生成经营日报、异常提醒和归因分析。', 'product.product.bizinsight.desc', ARRAY['智能数据','指标体系','BI Agent']::text[], 'developing', 'active', true, true, 'self', '{"zh":{"tagline":"数字员工 · 通用类","value":"让管理者从看报表转向问业务，快速定位收入、成本、交付和客户变化背后的原因。","highlights":["指标问答","异常归因","经营报告生成"],"tags":["智能数据","指标体系","BI Agent"],"industries":["general","operations"],"detail":""},"en":{"tagline":"Digital Employee · General","value":"Helps managers move from reading dashboards to asking business questions and finding root causes faster.","highlights":["Metric Q&A","Anomaly attribution","Business report generation"],"tags":["Intelligent Data","Metrics","BI Agent"],"industries":["general","operations"],"detail":""}}'::jsonb),
  (gen_random_uuid(), 'wargaming', 'industry_agent', 1, '战场推演智能体', 'Battlefield Simulation Agent', '面向复杂态势推演、资源约束评估和方案比选，构建可解释、可复盘的沙盘推演辅助能力。', 'product.product.wargaming.desc', ARRAY['数字孪生','仿真推演','智能体协同']::text[], 'developing', 'active', true, true, 'self', '{"zh":{"tagline":"强业务类 · 推演仿真","value":"帮助业务团队在安全边界内进行态势模拟和方案评估，提升推演效率和复盘质量。","highlights":["态势要素建模","方案比选推演","推演过程复盘"],"tags":["数字孪生","仿真推演","智能体协同"],"industries":["defense"],"detail":""},"en":{"tagline":"Industry Agent · Simulation","value":"Helps teams run situation simulation and plan evaluation within safety boundaries, improving simulation efficiency and review quality.","highlights":["Situation element modeling","Plan comparison simulation","Process review"],"tags":["Digital Twin","Simulation","Agent Collaboration"],"industries":["defense"],"detail":""}}'::jsonb),
