  (gen_random_uuid(), 'datagovernance', 'industry_agent', 1, '数据治理智能体', 'Data Governance Agent', '面向数据资产盘点、质量检查、口径解释和血缘分析，辅助企业持续建设智能数据底座。', 'product.product.datagovernance.desc', ARRAY['智能数据','元数据','数据质量']::text[], 'developing', 'active', true, true, 'self', '{"zh":{"tagline":"强业务类 · 数据治理","value":"降低数据治理门槛，让业务人员也能理解数据来源、质量问题和指标口径。","highlights":["数据资产问答","质量规则建议","指标口径解释"],"tags":["智能数据","元数据","数据质量"],"industries":["data","general","industry"],"detail":""},"en":{"tagline":"Industry Agent · Data Governance","value":"Lowers the barrier to data governance so business users can understand data sources, quality issues, and metric definitions.","highlights":["Data asset Q&A","Quality rule suggestions","Metric definition explanation"],"tags":["Intelligent Data","Metadata","Data Quality"],"industries":["data","general","industry"],"detail":""}}'::jsonb),
  (gen_random_uuid(), 'emergencyops', 'industry_agent', 1, '应急指挥智能体', 'Emergency Command Agent', '围绕突发事件态势汇聚、预案匹配、资源调度和任务跟踪，为指挥中心提供连续辅助。', 'product.product.emergencyops.desc', ARRAY['大模型研判','调度智能体','数字孪生']::text[], 'developing', 'active', true, true, 'self', '{"zh":{"tagline":"强业务类 · 应急管理","value":"把事件摘要、处置建议、队伍物资状态和回执统一到一条指挥链路。","highlights":["事件摘要","预案匹配","任务闭环跟踪"],"tags":["大模型研判","调度智能体","数字孪生"],"industries":["emergency"],"detail":""},"en":{"tagline":"Industry Agent · Emergency","value":"Unifies event summaries, response suggestions, team and supply status, and acknowledgements into one command chain.","highlights":["Event summary","Plan matching","Task loop tracking"],"tags":["LLM Assessment","Dispatch Agent","Digital Twin"],"industries":["emergency"],"detail":""}}'::jsonb),
  (gen_random_uuid(), 'urbanrisk', 'industry_agent', 1, '城市风险研判智能体', 'Urban Risk Assessment Agent', '整合人口、车辆、场所、事件和风险源数据，持续发现城市公共安全和治理风险。', 'product.product.urbanrisk.desc', ARRAY['智能数据','知识图谱','风险研判']::text[], 'developing', 'active', true, true, 'self', '{"zh":{"tagline":"强业务类 · 城市治理","value":"把跨部门线索转为可解释的风险清单和空间态势，辅助提前干预。","highlights":["多源线索融合","风险关联分析","空间态势展示"],"tags":["智能数据","知识图谱","风险研判"],"industries":["emergency","data"],"detail":""},"en":{"tagline":"Industry Agent · Urban Governance","value":"Turns cross-agency clues into explainable risk lists and spatial situation views for earlier intervention.","highlights":["Multi-source clue fusion","Risk relationship analysis","Spatial situation display"],"tags":["Intelligent Data","Knowledge Graph","Risk Assessment"],"industries":["emergency","data"],"detail":""}}'::jsonb),
